PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS tenants(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS branches(id TEXT PRIMARY KEY,tenant TEXT NOT NULL REFERENCES tenants(id),name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,tenant TEXT NOT NULL REFERENCES tenants(id),branch TEXT REFERENCES branches(id),name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('super','manager','reception','coach','finance','parent','student')));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS groups_data(id TEXT PRIMARY KEY,tenant TEXT NOT NULL REFERENCES tenants(id),branch TEXT NOT NULL REFERENCES branches(id),name TEXT NOT NULL,sport TEXT NOT NULL,level TEXT NOT NULL,coach TEXT NOT NULL REFERENCES users(id),days TEXT NOT NULL,start TEXT NOT NULL,end TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0));
CREATE TABLE IF NOT EXISTS children(id TEXT PRIMARY KEY,tenant TEXT NOT NULL REFERENCES tenants(id),name TEXT NOT NULL,dob TEXT NOT NULL,phone TEXT NOT NULL,email TEXT NOT NULL DEFAULT '',parent TEXT REFERENCES users(id),status TEXT NOT NULL DEFAULT 'active',created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,child TEXT NOT NULL REFERENCES children(id),group_id TEXT NOT NULL REFERENCES groups_data(id),starts TEXT NOT NULL,ends TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_current_group ON memberships(child) WHERE ends IS NULL;
CREATE TABLE IF NOT EXISTS subscriptions(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,child TEXT NOT NULL REFERENCES children(id),credits INTEGER NOT NULL CHECK(credits>=0),remaining INTEGER NOT NULL CHECK(remaining>=0),starts TEXT NOT NULL,expires TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0));
CREATE TABLE IF NOT EXISTS attendance(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,child TEXT NOT NULL REFERENCES children(id),group_id TEXT NOT NULL REFERENCES groups_data(id),membership TEXT NOT NULL REFERENCES memberships(id),subscription TEXT NOT NULL REFERENCES subscriptions(id),day TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('present','absent')),actor TEXT NOT NULL REFERENCES users(id),UNIQUE(child,day));
CREATE TABLE IF NOT EXISTS transfers(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,child TEXT NOT NULL REFERENCES children(id),old_group TEXT NOT NULL REFERENCES groups_data(id),new_group TEXT NOT NULL REFERENCES groups_data(id),reason TEXT NOT NULL,actor TEXT NOT NULL REFERENCES users(id),created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evaluations(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,child TEXT NOT NULL REFERENCES children(id),group_id TEXT NOT NULL REFERENCES groups_data(id),skill TEXT NOT NULL,score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100),notes TEXT NOT NULL,actor TEXT NOT NULL REFERENCES users(id),created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS staff(id TEXT PRIMARY KEY REFERENCES users(id),tenant TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN ('monthly','session','hour')),rate INTEGER NOT NULL CHECK(rate>=0));
CREATE TABLE IF NOT EXISTS staff_logs(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,staff TEXT NOT NULL REFERENCES staff(id),day TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('present','absent')),hours REAL NOT NULL CHECK(hours>=0 AND hours<=24),sessions INTEGER NOT NULL CHECK(sessions>=0),UNIQUE(staff,day));
CREATE TABLE IF NOT EXISTS adjustments(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,staff TEXT NOT NULL REFERENCES staff(id),month TEXT NOT NULL,amount INTEGER NOT NULL,reason TEXT NOT NULL,actor TEXT NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,child TEXT NOT NULL REFERENCES children(id),event TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'unconfigured',created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,entity TEXT NOT NULL,detail TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS registrations(id TEXT PRIMARY KEY,tenant TEXT NOT NULL REFERENCES tenants(id),branch TEXT NOT NULL REFERENCES branches(id),parent TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,dob TEXT NOT NULL,phone TEXT NOT NULL,email TEXT NOT NULL,group_id TEXT NOT NULL REFERENCES groups_data(id),status TEXT NOT NULL DEFAULT 'pending',created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS student_accounts(user_id TEXT PRIMARY KEY REFERENCES users(id),child TEXT NOT NULL UNIQUE REFERENCES children(id),tenant TEXT NOT NULL REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS tariffs(id TEXT PRIMARY KEY,tenant TEXT NOT NULL REFERENCES tenants(id),branch TEXT NOT NULL REFERENCES branches(id),sport TEXT NOT NULL,level TEXT NOT NULL DEFAULT '',name TEXT NOT NULL,credits INTEGER NOT NULL CHECK(credits>0),duration INTEGER NOT NULL CHECK(duration>0),amount INTEGER NOT NULL CHECK(amount>=0),enabled INTEGER NOT NULL DEFAULT 1);
